def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    op = [h[1] for h in history]
    if 'D' not in op:
        return 'D'
    if 'C' not in op:
        return 'D'
    if len(op) >= 5 and op[-5:] == ['D', 'D', 'D', 'D', 'D']:
        return 'D'
    my = [h[0] for h in history]
    if 'D' in my[-5:]:
        return 'C'
    if op[-1] == 'D':
        return 'D'
    return 'C'
